return ['x-generator'=>'GlotPress/4.1.0','translation-revision-date'=>'2026-10-12 18:43:03+0000','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','project-id-version'=>'Plugins - Jetpack &#8211; WP Security, Backup, Speed, &amp; Growth - Stable (latest release)','language'=>'uk_UA','messages'=>['WordPress.com Connection'=>'Підключення WordPress.com','block keywordappointment'=>'зустріч','block keywordscheduling'=>'планування','block descriptionEmbed a Zoom Scheduler booking page.'=>'Вставити сторінку планування зустрічей Zoom.','block titleZoom Scheduler'=>'Планувальник Zoom','block keyworddynamic'=>'динамічний','block keywordrecent'=>'нещодавній','block keywordnewest'=>'найновіший','block keywordlatest'=>'останній','block descriptionVideoPress powered list of your latest videos in a single customizable player. New uploads show up automatically.'=>'Список ваших останніх відео на основі VideoPress в одному програвачі який можна налаштувати. Нові завантаження з’являються автоматично.','block titleLatest Videos Playlist'=>'Останні відео - список відтворення','block keywordcollection'=>'колекція','block keywordplaylists'=>'списки відтворення','block descriptionEvery playlist on the site, paginated, under a heading you can edit.'=>'Усі списки відтворення на сайті з поділом на сторінки та заголовком, який можна редагувати.','block titleAll Playlists'=>'Всі списки відтворення','block keywordpayment'=>'оплата','block keywordpaypal'=>'paypal','block descriptionAccept payments via PayPal. Create a buy button directly in the editor — no code required.'=>'Приймайте платежі через PayPal. Створити кнопку «Купити» безпосередньо в редакторі - код не потрібен.','The site verification code is invalid.'=>'Код підтвердження сайту недійсний.','The requested Jetpack module is enabled by your host or site administrator, so it stays on.'=>'Запитуваний модуль Jetpack увімкнено